SourceCode.Declaration:
/// <summary>
/// This is an extension class for the VendParameters form METVendParameters_EnableMetcashMatchingLogic control.
/// </summary>
[ExtensionOf(formControlStr(VendParameters, METVendParameters_EnableMetcashMatchingLogic))]
final class METVendParameters_EnableMetcashMatchingLogicCtrl_Extension
{
}

Method.Source:
/// <summary>
/// Enable/disable the EnableMetcashMatchingLogic control.
/// </summary>
/// <returns>Boolean value</returns>
public boolean modified()
{
    boolean ret;

    ret = next modified();

    FormControl ctrl = this;
    FormRun formRun =  ctrl.formRun();
    METVendParameters vendparm = formRun.dataSource(formDataSourceStr(VendParameters, METVendParameters)).cursor();
    FormControl taxinvTotCtrl = formRun.design(1).controlName(formControlStr(VendParameters, METVendParameters_TaxInvTotalsToleranceDollar));
    FormControl totTolPercCtrl = formRun.design(1).controlName(formControlStr(VendParameters, METInvoiceMatching_TotalPriceTolerancePercentage));
    FormControl displayTotalPriceMatchCtrl = formRun.design(1).controlName(formControlStr(VendParameters, METVendParameters_DisplayTotalPriceMatchIcon));
    FormControl defaultInvDate = this.formRun().design(1).controlName(formControlStr(VendParameters, VendParameters_METDefaultInvDate));
    FormControl metReasonCode = this.formRun().design(1).controlName(formControlStr(VendParameters, VendParameters_METReasonCode));
    FormControl displayHideCustomFields = this.formRun().design(1).controlName(formControlStr(VendParameters, METVendParameters_DisplayHideCustomFields));

    if (vendparm.EnableMetcashMatchingLogic)
    {
        taxinvTotCtrl.enabled(true);
        totTolPercCtrl.enabled(true);
        displayTotalPriceMatchCtrl.enabled(true);
        defaultInvDate.enabled(true);
        metReasonCode.enabled(true);
        displayHideCustomFields.enabled(true);
    }
    else
    {
        taxinvTotCtrl.enabled(false);
        totTolPercCtrl.enabled(false);
        displayTotalPriceMatchCtrl.enabled(false);
        defaultInvDate.enabled(false);
        metReasonCode.enabled(false);
        displayHideCustomFields.enabled(false);
    }

    return ret;
}
